/* SC-200 Cert Gauntlet — cards, domain 3 "Perform threat hunting" */
export const SC200_CARDS_D3 = [
 /* ---------- kql: 3.1.1 table selection ---------- */
 {c:"kql",obj:"3.1.1",q:"Which table — a new process started on an endpoint (command line, parent)",
  a:"#DeviceProcessEvents\nActionType ProcessCreated; ProcessCommandLine, FileName, SHA1\nInitiatingProcess* columns describe the parent",s:"DeviceProcessEvents",g:"devtable",
  k:"DeviceProcessEvents\n| where FileName =~ 'powershell.exe'\n| where ProcessCommandLine has_any ('-enc','DownloadString')\n| project Timestamp, DeviceName, ProcessCommandLine, InitiatingProcessFileName",
  x:"DeviceProcessEvents is the Defender for Endpoint table that records process creation. The created process is described by FileName, FolderPath, ProcessCommandLine, the hash columns and ProcessTokenElevation, while every InitiatingProcess* column describes the parent that launched it. Stems about 'suspicious command line', 'living-off-the-land binary' or 'child process of Word' point here rather than at DeviceEvents.",
  w:"Process born = DeviceProcessEvents; the parent lives in InitiatingProcess*."},
 {c:"kql",obj:"3.1.1",q:"Which table — outbound connections from a device to an IP, port or URL",
  a:"#DeviceNetworkEvents\nRemoteIP, RemotePort, RemoteUrl, LocalIP, Protocol, RemoteIPType\nActionType ConnectionSuccess / ConnectionFailed / InboundConnectionAccepted",s:"DeviceNetworkEvents",g:"devtable",
  k:"DeviceNetworkEvents\n| where RemoteIPType == 'Public' and RemotePort in (4444, 8443)\n| summarize count() by DeviceName, RemoteIP, InitiatingProcessFileName",
  x:"DeviceNetworkEvents captures network connections observed by the endpoint sensor, including the initiating process. RemoteIPType lets you drop private and loopback traffic quickly, and RemoteUrl holds the FQDN when the sensor saw one. If the question is about C2 beaconing, rare destination ports or which process reached an IP, this is the table; DNS and proxy logs from other sources land in Sentinel tables instead.",
  w:"Where did the device talk to? DeviceNetworkEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — a file was created, modified, renamed or downloaded on a device",
  a:"#DeviceFileEvents\nActionType FileCreated / FileModified / FileRenamed / FileDeleted\nFileOriginUrl and FileOriginReferrerUrl show where a download came from",s:"DeviceFileEvents",g:"devtable",
  k:"DeviceFileEvents\n| where ActionType == 'FileCreated' and FolderPath has 'Downloads'\n| where isnotempty(FileOriginUrl)\n| project Timestamp, DeviceName, FileName, FileOriginUrl, SHA256",
  x:"DeviceFileEvents records file system activity seen by Defender for Endpoint. Its origin columns (FileOriginUrl, FileOriginReferrerUrl, FileOriginIP) are the quickest way to answer 'which site did this payload come from', and PreviousFileName/PreviousFolderPath expose renames and moves. Share-related columns (ShareName, RequestProtocol, RequestSourceIP) help with lateral tool transfer over SMB. Hash columns can be empty for locked or compressed files.",
  w:"Dropped file or download origin = DeviceFileEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — a Run key or other registry value was written for persistence",
  a:"#DeviceRegistryEvents\nActionType RegistryValueSet / RegistryKeyCreated / RegistryKeyDeleted\nRegistryKey, RegistryValueName, RegistryValueData, Previous* columns",s:"DeviceRegistryEvents",g:"devtable",
  k:"DeviceRegistryEvents\n| where ActionType == 'RegistryValueSet'\n| where RegistryKey has @'\\CurrentVersion\\Run'\n| project Timestamp, DeviceName, RegistryValueName, RegistryValueData, InitiatingProcessFileName",
  x:"DeviceRegistryEvents is the endpoint table for registry key and value changes. PreviousRegistryValueData and PreviousRegistryKey let you compare before and after a modification, which is useful for detecting tampering with security settings. Exam stems that mention autostart entries, Run keys, Image File Execution Options or disabling Defender through the registry are pointing at this table rather than DeviceEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — interactive or RDP sign-ins on an endpoint, including failures",
  a:"#DeviceLogonEvents\nActionType LogonSuccess / LogonFailed; LogonType Interactive, RemoteInteractive, Network…\nIsLocalAdmin, RemoteIP, RemoteDeviceName, FailureReason",s:"DeviceLogonEvents",g:"devtable",
  k:"DeviceLogonEvents\n| where ActionType == 'LogonFailed'\n| summarize Failures = count(), dcount(AccountName) by RemoteIP, DeviceName\n| where Failures > 20",
  x:"DeviceLogonEvents comes from the Defender for Endpoint sensor and records logon sessions on the device itself. LogonType values such as RemoteInteractive (RDP), Network and Interactive, together with RemoteIP and IsLocalAdmin, make it the table for brute force against a host or an attacker landing on a box with admin rights. Contrast with IdentityLogonEvents, which is authentication seen by domain controllers and cloud services rather than the endpoint.",
  w:"Logon ON the device = DeviceLogonEvents; logon seen BY the DC = IdentityLogonEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — ASR blocks, antivirus detections, PowerShell commands, USB mounts",
  a:"#DeviceEvents\nGrab-bag table keyed by ActionType\nAntivirusDetection, AsrLsassCredentialTheftBlocked, PowerShellCommand, UsbDriveMounted…",s:"DeviceEvents",g:"devtable",
  k:"DeviceEvents\n| where ActionType startswith 'Asr' and ActionType endswith 'Blocked'\n| summarize count() by ActionType, DeviceName",
  x:"DeviceEvents holds the event types that do not fit the dedicated process, file, network, registry or logon tables: security-control outcomes such as ASR rule blocks and audits, antivirus detections, network protection and SmartScreen events, PowerShell command logging, scheduled task creation and removable media. AdditionalFields carries event-specific JSON. When a stem names a Defender feature firing, filter DeviceEvents by ActionType; the portal schema reference lists the values.",
  w:"If the question names a Defender feature, the answer is usually DeviceEvents + ActionType."},
 {c:"kql",obj:"3.1.1",q:"Which table — a DLL was loaded into a process",
  a:"#DeviceImageLoadEvents\nDLL load events with FileName, FolderPath, SHA1 of the module\nInitiatingProcess* identifies the loading process",s:"DeviceImageLoadEvents",g:"devtable",
  k:"DeviceImageLoadEvents\n| where FileName =~ 'wmiutils.dll' or FolderPath has 'Temp'\n| project Timestamp, DeviceName, FileName, FolderPath, InitiatingProcessFileName",
  x:"DeviceImageLoadEvents is the dedicated table for module (DLL) loads on endpoints. It is the right pick for DLL side-loading and search-order hijacking hunts, where the question is which process loaded an unexpected library from an unusual path. Process creation does not record loaded modules, so DeviceProcessEvents cannot answer it; the loaded DLL is in FileName and the host process is in the InitiatingProcess* columns."},
 {c:"kql",obj:"3.1.1",q:"Which table — current OS, onboarding state, device group and logged-on users of a device",
  a:"#DeviceInfo (periodic snapshots)\nOSPlatform, OnboardingStatus, MachineGroup, LoggedOnUsers, ExposureLevel, PublicIP\nUse summarize arg_max(Timestamp, *) by DeviceId for the latest row",s:"DeviceInfo",g:"devtable",
  k:"DeviceInfo\n| where isnotempty(OSPlatform)\n| summarize arg_max(Timestamp, *) by DeviceId\n| where OnboardingStatus != 'Onboarded' or SensorHealthState != 'Active'",
  x:"DeviceInfo is an inventory-style table: each row is a periodic snapshot of a device, not an event, so queries usually collapse it with arg_max to get the newest record per DeviceId. It carries machine group (RBAC scope), manual and dynamic tags, join type, exposure level and sensor health. Adapter-level details (MAC, IP addresses per interface, network adapter type) are in the companion DeviceNetworkInfo table rather than here.",
  w:"DeviceInfo is a snapshot table: arg_max first, filter second."},
 {c:"kql",obj:"3.1.1",q:"Which table — vulnerable software per device with CVE and recommended update",
  a:"#DeviceTvmSoftwareVulnerabilities\nCveId, VulnerabilitySeverityLevel, SoftwareName/Version, RecommendedSecurityUpdate\nNo Timestamp column: it is a snapshot; join the KB table for CVSS and exploit availability",s:"DeviceTvmSoftwareVulnerabilities",g:"devtable",
  k:"DeviceTvmSoftwareVulnerabilities\n| where VulnerabilitySeverityLevel == 'Critical'\n| join kind=inner (DeviceTvmSoftwareVulnerabilitiesKB | where IsExploitAvailable) on CveId\n| summarize dcount(DeviceId) by CveId, SoftwareName",
  x:"The DeviceTvm* family comes from Defender Vulnerability Management. DeviceTvmSoftwareVulnerabilities lists each device and CVE pair with the vendor's fix, while DeviceTvmSoftwareVulnerabilitiesKB is the knowledge base with CvssScore, PublishedDate and IsExploitAvailable. Because these tables are current-state snapshots without Timestamp, you cannot ask 'when' from them; use DeviceTvmSoftwareInventory for installed software and DeviceTvmSecureConfigurationAssessment for misconfigurations."},
 {c:"kql",obj:"3.1.1",q:"Which table — inbound email verdicts, delivery action and sender/recipient",
  a:"#EmailEvents\nNetworkMessageId, SenderFromAddress, RecipientEmailAddress, Subject, ThreatTypes\nEmailDirection Inbound/Outbound/Intra-org; DeliveryAction Delivered/Junked/Blocked/Replaced",s:"EmailEvents",g:"mailtable",
  k:"EmailEvents\n| where EmailDirection == 'Inbound' and ThreatTypes has 'Phish'\n| where DeliveryAction == 'Delivered'\n| project Timestamp, NetworkMessageId, SenderFromAddress, RecipientEmailAddress, Subject, DeliveryLocation",
  x:"EmailEvents is the Defender for Office 365 table with one row per message and recipient at delivery time. ThreatTypes and DetectionMethods hold the verdict, DeliveryAction and DeliveryLocation say what happened, and LatestDeliveryAction/LatestDeliveryLocation reflect later admin or ZAP changes. NetworkMessageId is the key that joins to the attachment, URL, post-delivery and click tables, so almost every mail hunt starts here.",
  w:"Mail hunts start at EmailEvents and pivot on NetworkMessageId."},
 {c:"kql",obj:"3.1.1",q:"Which tables — attachment hashes and URLs inside a message",
  a:"#EmailAttachmentInfo and EmailUrlInfo\nAttachmentInfo: FileName, FileType, SHA256; UrlInfo: Url, UrlDomain\nBoth join to EmailEvents on NetworkMessageId",s:"EmailAttachmentInfo or EmailUrlInfo",g:"mailtable",
  k:"EmailEvents\n| join kind=inner (EmailAttachmentInfo | where FileType in ('iso','lnk','js')) on NetworkMessageId\n| project Timestamp, SenderFromAddress, RecipientEmailAddress, FileName, SHA256",
  x:"EmailEvents does not list each attachment or URL; those live in EmailAttachmentInfo (one row per attachment with its SHA256 and file type) and EmailUrlInfo (one row per URL with its domain). To answer 'which users received a file with hash X' or 'who got a link to domain Y', join either table to EmailEvents on NetworkMessageId. Clicks on those links are a third table, UrlClickEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — messages removed after delivery by ZAP or an admin",
  a:"#EmailPostDeliveryEvents\nActionType Phish ZAP / Malware ZAP / Manual remediation\nActionTrigger, Action, ActionResult, DeliveryLocation",s:"EmailPostDeliveryEvents",g:"mailtable",
  k:"EmailPostDeliveryEvents\n| where ActionType in ('Phish ZAP','Malware ZAP')\n| join kind=inner EmailEvents on NetworkMessageId\n| project Timestamp, RecipientEmailAddress, Subject, Action, ActionResult",
  x:"EmailPostDeliveryEvents records what happened to a message after it reached a mailbox: zero-hour auto purge moving a late-identified phish or malware message, or an administrator's manual remediation from Threat Explorer or an approved automated investigation. If the stem says 'was delivered and later removed' or 'ZAP', this is the table; EmailEvents only tells you the verdict at delivery time."},
 {c:"kql",obj:"3.1.1",q:"Which table — did a user actually click a Safe Links URL, and was it blocked",
  a:"#UrlClickEvents\nActionType ClickAllowed / ClickBlocked / ClickBlockedByTenantPolicy / UrlScanInProgress\nIsClickedThrough; Workload Email / Office / Teams",s:"UrlClickEvents",g:"mailtable",
  k:"UrlClickEvents\n| where ThreatTypes has 'Phish'\n| where ActionType == 'ClickAllowed' or IsClickedThrough\n| project Timestamp, AccountUpn, Url, ActionType, Workload, NetworkMessageId",
  x:"UrlClickEvents captures Safe Links click-time decisions across email, Office apps and Teams. IsClickedThrough is the important flag: the user saw the warning page and proceeded anyway, which usually means the account needs attention. EmailUrlInfo only proves a link was present in a message; UrlClickEvents proves someone clicked it, and NetworkMessageId links the click back to the original mail.",
  w:"Link present = EmailUrlInfo; link clicked = UrlClickEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — Kerberos/NTLM authentications seen by domain controllers or cloud apps",
  a:"#IdentityLogonEvents\nFed by Defender for Identity (AD) and Defender for Cloud Apps (online services)\nActionType LogonSuccess/LogonFailed; Protocol Kerberos, NTLM, LDAP; LogonType",s:"IdentityLogonEvents",g:"idtable",
  k:"IdentityLogonEvents\n| where Protocol == 'NTLM' and ActionType == 'LogonFailed'\n| summarize count(), make_set(AccountName, 20) by IPAddress, bin(Timestamp, 1h)",
  x:"IdentityLogonEvents is the identity-side authentication table. Defender for Identity sensors on domain controllers contribute on-premises logons (including protocol and failure reason), and Defender for Cloud Apps contributes sign-ins to Microsoft online services. Pick it for password spray against AD, NTLM relay style activity or legacy protocol use; pick DeviceLogonEvents when the question is about sessions on a specific endpoint, and SigninLogs for raw Entra sign-in detail in Sentinel."},
 {c:"kql",obj:"3.1.1",q:"Which table — LDAP or SAMR enumeration of users, groups and admins",
  a:"#IdentityQueryEvents\nActionType LDAP query / SAMR query / DNS query\nQueryType, QueryTarget, Query; TargetAccountUpn, DestinationDeviceName",s:"IdentityQueryEvents",g:"idtable",
  k:"IdentityQueryEvents\n| where ActionType == 'SAMR query' and QueryTarget has 'Admins'\n| summarize count() by AccountUpn, DeviceName, QueryTarget",
  x:"IdentityQueryEvents, populated by Defender for Identity, records reconnaissance-style directory queries: LDAP searches, SAM-R enumeration of local or domain groups, and DNS queries against the DC. Discovery techniques such as account and group enumeration (BloodHound style collection) show up here. It is distinct from IdentityDirectoryEvents, which records changes to the directory rather than reads of it.",
  w:"Reading AD = IdentityQueryEvents; changing AD = IdentityDirectoryEvents."},
 {c:"kql",obj:"3.1.1",q:"Which table — password changes, group membership changes, replication requests in AD",
  a:"#IdentityDirectoryEvents\nActionType examples: Account Password changed, Group Membership changed, Directory Services replication\nTargetAccountUpn, DestinationDeviceName, AdditionalFields",s:"IdentityDirectoryEvents",g:"idtable",
  k:"IdentityDirectoryEvents\n| where ActionType == 'Group Membership changed'\n| extend Grp = tostring(AdditionalFields['TO.GROUP'])\n| where Grp has 'Domain Admins'\n| project Timestamp, AccountName, TargetAccountUpn, Grp",
  x:"IdentityDirectoryEvents is the Defender for Identity table for on-premises Active Directory changes and domain controller events: credential and account changes, group membership edits, SMB sessions and directory replication (the signal behind DCSync hunts). The event-specific detail is packed into the AdditionalFields dynamic column, so most useful queries extend a value out of it before filtering. Cloud directory changes are in AuditLogs or CloudAppEvents instead."},
 {c:"kql",obj:"3.1.1",q:"Which table — activity inside SaaS and M365 apps (inbox rules, sharing, admin ops)",
  a:"#CloudAppEvents\nDefender for Cloud Apps connected apps: Exchange, SharePoint, Teams, Dropbox, Salesforce, GitHub…\nApplication, ActionType, AccountObjectId, IsAdminOperation, RawEventData",s:"CloudAppEvents",g:"idtable",
  k:"CloudAppEvents\n| where Application == 'Microsoft Exchange Online' and ActionType == 'New-InboxRule'\n| extend Params = tostring(RawEventData.Parameters)\n| project Timestamp, AccountDisplayName, IPAddress, CountryCode, Params",
  x:"CloudAppEvents carries enriched activity logs for every app connected to Defender for Cloud Apps, including Microsoft 365 workloads once the Office 365 connector is enabled. The original record is kept in RawEventData, so inbox-rule parameters, file names and OAuth consent details are extracted from JSON. It is the XDR counterpart of Sentinel's OfficeActivity table and the place to hunt BEC indicators such as forwarding rules created from a new country."},
 {c:"kql",obj:"3.1.1",q:"Which tables — alert metadata and the entities each alert involved",
  a:"#AlertInfo + AlertEvidence, joined on AlertId\nAlertInfo: Title, Severity, Category, ServiceSource, DetectionSource, AttackTechniques\nAlertEvidence: EntityType, EvidenceRole Impacted/Related, SHA1, RemoteIP, AccountUpn…",s:"AlertInfo joined to AlertEvidence",g:"alerttable",
  k:"AlertInfo\n| where Severity == 'High' and ServiceSource == 'Microsoft Defender for Identity'\n| join kind=inner AlertEvidence on AlertId\n| where EntityType == 'User'\n| project Timestamp, Title, AccountUpn, EvidenceRole",
  x:"Alerts are split across two tables: AlertInfo has one row per alert with its title, severity, category, MITRE techniques and which Defender product raised it, while AlertEvidence has one row per entity (user, device, file, IP, URL, mailbox) attached to the alert. Any question that combines 'alerts about X' with 'which users or files were involved' needs a join on AlertId. In Sentinel the equivalent is SecurityAlert with entities packed in a JSON column."},
 {c:"kql",obj:"3.1.1",q:"Which table — Entra ID user sign-ins vs service principal sign-ins in advanced hunting",
  a:"#AADSignInEventsBeta (users, interactive + non-interactive) vs AADSpnSignInEventsBeta (service principals, managed identities)\nNewer names EntraIdSignInEvents / EntraIdSpnSignInEvents\nRequire a Microsoft Entra ID P2 license",s:"AADSignInEventsBeta vs AADSpnSignInEventsBeta",g:"idtable",
  k:"AADSignInEventsBeta\n| where ErrorCode == 0 and RiskLevelDuringSignIn >= 50\n| summarize count() by AccountUpn, Country, Application",
  x:"Advanced hunting exposes Entra sign-ins in two tables: the user table covers interactive and non-interactive sign-ins with error codes, conditional access results and risk level, and the SPN table covers service principal and managed identity sign-ins. Microsoft now lists EntraIdSignInEvents and EntraIdSpnSignInEvents alongside the older Beta names. In a Sentinel workspace the comparable data is SigninLogs and AADServicePrincipalSignInLogs."},
 {c:"kql",obj:"3.1.1",q:"Which tables — query the exposure graph (assets and their relationships) in KQL",
  a:"#ExposureGraphNodes and ExposureGraphEdges\nNodes: NodeId, NodeLabel, NodeName, Categories, NodeProperties, EntityIds\nEdges: EdgeLabel with SourceNodeId / TargetNodeId",s:"ExposureGraphNodes and ExposureGraphEdges",g:"alerttable",
  k:"ExposureGraphEdges\n| where EdgeLabel == 'has permissions to'\n| join kind=inner (ExposureGraphNodes | where NodeLabel == 'user') on $left.SourceNodeId == $right.NodeId\n| project NodeName, TargetNodeLabel, TargetNodeId",
  x:"Microsoft Security Exposure Management stores its enterprise exposure graph in two advanced hunting tables. ExposureGraphNodes lists every asset with a JSON NodeProperties bag that includes exposure insights such as internet exposure or critical-asset status, and ExposureGraphEdges lists directed relationships between node IDs. Hunting a path to a critical asset in KQL means chaining edge joins; the hunting graph UI does the same visually."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel table — Windows Security event IDs such as 4624, 4688, 4720",
  a:"#SecurityEvent\nFilled by Windows Security Events via AMA (and WEF forwarding)\nEventID, Account, Computer, LogonType, CommandLine, SubjectUserName",s:"SecurityEvent",g:"senttable",
  k:"SecurityEvent\n| where EventID == 4688 and CommandLine has 'mimikatz'\n| project TimeGenerated, Computer, SubjectUserName, CommandLine",
  x:"SecurityEvent is the Log Analytics table that receives Windows Security log entries collected by the Azure Monitor Agent through a data collection rule, or forwarded from a WEF collector. Questions phrased with raw event IDs (4624 logon, 4625 failure, 4688 process creation, 4720 account created, 4728 group membership) are SecurityEvent questions. Defender for Endpoint telemetry about the same activity lives in the Device* tables, with no event IDs.",
  w:"Event ID in the stem = SecurityEvent."},
 {c:"kql",obj:"3.1.1",q:"Sentinel tables for alerts vs incidents — what each row represents",
  a:"#SecurityAlert = one row per alert (and update); SecurityIncident = one row per incident state change\nSecurityAlert: AlertName, ProviderName, Entities (JSON), Tactics, SystemAlertId\nSecurityIncident: IncidentNumber, Status, Severity, Owner, AlertIds, ClassificationReason",s:"SecurityAlert vs SecurityIncident",g:"senttable",
  k:"SecurityIncident\n| summarize arg_max(TimeGenerated, *) by IncidentNumber\n| where Status == 'Active'\n| mv-expand AlertId = AlertIds\n| join kind=inner (SecurityAlert | project SystemAlertId, AlertName, ProviderName) on $left.AlertId == $right.SystemAlertId",
  x:"In a Sentinel workspace alerts from every connected product land in SecurityAlert, and the incidents built from them are logged in SecurityIncident. Both tables are append-only histories, so each status or owner change writes a fresh SecurityIncident row and you collapse with arg_max by IncidentNumber before reporting. AlertIds is a JSON array of SystemAlertId values, which is the join key back to the alerts. Mean-time-to-close workbooks are built on these two tables."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel tables — Entra ID sign-ins vs directory audit changes",
  a:"#SigninLogs vs AuditLogs\nSigninLogs: ResultType, ConditionalAccessStatus, RiskLevelDuringSignIn, Location, AppDisplayName\nAuditLogs: OperationName, Category, InitiatedBy, TargetResources",s:"SigninLogs vs AuditLogs",g:"senttable",
  k:"SigninLogs\n| where ResultType == 0 and RiskLevelDuringSignIn == 'high'\n| summarize count() by UserPrincipalName, IPAddress, AppDisplayName",
  x:"The Microsoft Entra ID connector streams two core tables. SigninLogs is every authentication attempt with result code, MFA and conditional access outcome, device and risk detail, which makes it the home of password spray, impossible travel and MFA fatigue hunts. AuditLogs is what changed in the directory: role assignments, app consents, user and group edits, with the actor in InitiatedBy and the object in TargetResources. Non-interactive and service principal sign-ins have their own AAD* tables."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel table — CEF firewall logs vs plain syslog from a Linux forwarder",
  a:"#CommonSecurityLog (CEF via AMA) vs Syslog (Syslog via AMA)\nCommonSecurityLog: DeviceVendor, DeviceProduct, DeviceAction, SourceIP, DestinationIP, DestinationPort\nSyslog: Facility, SeverityLevel, ProcessName, SyslogMessage",s:"CommonSecurityLog vs Syslog",g:"senttable",
  k:"CommonSecurityLog\n| where DeviceVendor == 'Palo Alto Networks' and DeviceAction == 'deny'\n| summarize Denied = count() by SourceIP, DestinationPort\n| top 20 by Denied",
  x:"Both connectors ride the Azure Monitor Agent on a Linux log forwarder, but they land in different tables. CEF-formatted messages are parsed into the typed columns of CommonSecurityLog, so firewall, proxy and IDS vendors that emit CEF are queried there. Everything else that arrives as raw syslog stays in the Syslog table with the text in SyslogMessage and needs parse or extract to pull fields out. Using the same facility for both connectors duplicates data.",
  w:"CEF = CommonSecurityLog; everything else over syslog = Syslog."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel tables — Microsoft 365 workload activity vs Azure control-plane operations",
  a:"#OfficeActivity vs AzureActivity\nOfficeActivity: OfficeWorkload (Exchange, SharePoint, OneDrive, Teams), Operation, UserId, ClientIP\nAzureActivity: OperationNameValue, Caller, ResourceGroup, ActivityStatusValue, CallerIpAddress",s:"OfficeActivity vs AzureActivity",g:"senttable",
  k:"OfficeActivity\n| where OfficeWorkload == 'Exchange' and Operation in ('New-InboxRule','Set-InboxRule','Set-Mailbox')\n| project TimeGenerated, UserId, Operation, ClientIP, Parameters",
  x:"OfficeActivity is the Sentinel copy of the Microsoft 365 unified audit log for Exchange, SharePoint, OneDrive and Teams, so mailbox rule creation, mass downloads and sharing changes are hunted there. AzureActivity is the Azure subscription activity log: who created, deleted or modified Azure resources, role assignments and key vault policies, with the identity in Caller. A question about SharePoint files goes to the first; a question about a VM or NSG change goes to the second."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel tables — threat indicators and STIX objects for TI matching",
  a:"#ThreatIntelIndicators (indicators) and ThreatIntelObjects (actors, attack patterns, relationships)\nReplaced the legacy ThreatIntelligenceIndicator table (ingestion stopped July 31, 2025)\nMatch on ObservableValue / ObservableKey, check IsActive and ValidUntil",s:"ThreatIntelIndicators and ThreatIntelObjects",g:"senttable",
  k:"let ioc = ThreatIntelIndicators\n| where IsActive and ObservableKey == 'ipv4-addr:value'\n| project Ioc = tostring(ObservableValue);\nCommonSecurityLog\n| where DestinationIP in (ioc)",
  x:"Sentinel now stores imported threat intelligence in two tables. ThreatIntelIndicators holds the observables (IPs, domains, URLs, hashes, certificates, user agents) with validity and confidence, and ThreatIntelObjects holds the surrounding STIX objects such as threat actors and relationships. The older ThreatIntelligenceIndicator table no longer receives data, so hunting queries, analytics rules and workbooks written against it must be migrated.",
  w:"New TI tables are plural: ThreatIntelIndicators and ThreatIntelObjects."},
 {c:"kql",obj:"3.1.1",q:"Which Sentinel tables — UEBA anomaly scores, peer groups and enriched account data",
  a:"#BehaviorAnalytics (InvestigationPriority 0–10, ActivityInsights, UsersInsights)\nUserPeerAnalytics ranks a user's peers; IdentityInfo is the enriched account directory\nIdentityInfo fully re-syncs every 14 days, incremental changes within minutes",s:"BehaviorAnalytics, UserPeerAnalytics and IdentityInfo",g:"senttable",
  k:"BehaviorAnalytics\n| where InvestigationPriority >= 7\n| where ActivityInsights.FirstTimeUserConnectedFromCountry == true\n| join kind=inner (IdentityInfo | summarize arg_max(TimeGenerated, *) by AccountUPN) on $left.UserPrincipalName == $right.AccountUPN\n| project TimeGenerated, UserPrincipalName, SourceIPLocation, AssignedRoles, BlastRadius",
  x:"Enabling UEBA adds tables Sentinel generates itself. BehaviorAnalytics scores every analyzed activity with an InvestigationPriority and explains it in dynamic insight columns (first time from this country, uncommon among peers, and so on). UserPeerAnalytics lists each user's calculated peers for comparison, and IdentityInfo is the enrichment directory with roles, group membership (up to 500 groups), manager and blast radius, drawn from Entra ID and from Defender for Identity for on-premises AD."},
 /* ---------- kql: 3.1.2 operators and functions ---------- */
 {c:"kql",obj:"3.1.2",q:"where vs project vs project-away vs project-rename vs extend",
  a:"#where filters rows; project picks/renames columns; extend adds computed columns\nproject-away drops named columns, keeping the rest\nproject-rename changes names without dropping anything",s:"Row filter vs column shaping vs computed column",g:"shape",
  k:"DeviceProcessEvents\n| where Timestamp > ago(7d)\n| extend Cmd = tolower(ProcessCommandLine)\n| project-rename Host = DeviceName\n| project-away ReportId, MD5",
  x:"These are the row and column shaping operators every hunting query uses. where keeps rows that satisfy a predicate; project returns only the listed columns (and can rename or compute inline); project-away removes a few columns while keeping everything else; project-rename renames in place; extend appends new calculated columns without discarding existing ones. Exam distractors swap project and extend, so remember that project narrows and extend widens.",
  w:"project narrows, extend widens, where thins."},
 {c:"kql",obj:"3.1.2",q:"summarize — grouping with count(), dcount(), countif(), make_set(), arg_max()",
  a:"#summarize aggregates rows into one row per group (the by clause)\ncount rows, dcount distinct values, countif conditional, make_set/make_list collect values\narg_max(Timestamp, *) returns the whole latest row per group",s:"Group rows and compute aggregates per group",g:"shape",
  k:"DeviceLogonEvents\n| where ActionType == 'LogonFailed'\n| summarize Attempts = count(), Users = dcount(AccountName), Names = make_set(AccountName, 10),\n    Last = arg_max(Timestamp, RemoteIP) by DeviceName",
  x:"summarize is the aggregation operator: it groups rows by the columns after by and computes functions over each group. count() and countif() produce totals, dcount() counts distinct values, sum/avg/min/max/percentile handle numeric columns, make_set and make_list collect values into a dynamic array, and arg_max/arg_min return the row with the highest or lowest value of an expression. Threshold-style detections ('more than 10 failures from one IP') are summarize followed by where.",
  w:"summarize = GROUP BY; arg_max = 'give me the newest row'."},
 {c:"kql",obj:"3.1.2",q:"bin() with summarize — bucketing events into time windows",
  a:"#bin(Timestamp, 1h) rounds each timestamp down to its bucket\nUsed in the by clause to count per interval\nPairs with render timechart for trend visualisation",s:"Round timestamps into fixed buckets for time series",g:"shape",
  k:"DeviceNetworkEvents\n| where RemoteIPType == 'Public'\n| summarize Connections = count() by bin(Timestamp, 15m), DeviceName\n| render timechart",
  x:"bin() (alias floor) rounds a value down to the nearest multiple of the bin size, so summarize by bin(Timestamp, 1h) yields one row per device per hour. It is the standard way to build a time series for beaconing analysis, spikes in failed logons or hourly email volume. Without bin, grouping by a raw timestamp produces one group per event. Remember bin on the datetime column, not on count."},
 {c:"kql",obj:"3.1.2",q:"join kinds — innerunique (default), inner, leftouter, leftanti, leftsemi, fullouter",
  a:"#Default kind is innerunique: dedupes left-side keys before matching\ninner keeps all matches; leftouter keeps every left row (nulls on no match)\nleftanti = left rows with NO match; leftsemi = left rows WITH a match, right columns dropped",s:"innerunique is default; leftanti finds what is missing",g:"combine",
  k:"// devices seen by Defender but with no heartbeat in Sentinel\nDeviceInfo | summarize arg_max(Timestamp, *) by DeviceName\n| join kind=leftanti (Heartbeat | distinct Computer) on $left.DeviceName == $right.Computer",
  x:"join combines two tables on a key. The default flavor is innerunique, which keeps one left row per key, so an explicit kind=inner is needed when you want every matching combination. leftouter preserves unmatched left rows, rightouter and fullouter do the same for the other side or both, leftanti returns left rows without a match (perfect for 'which devices are missing'), and leftsemi returns matched left rows without adding right columns. Use $left and $right when the key column names differ, and put the smaller table on the left.",
  w:"Forget kind= and you get innerunique; 'not in the other table' = leftanti."},
 {c:"kql",obj:"3.1.2",q:"union vs join — stacking tables vs matching rows",
  a:"#union appends rows from several tables (same or different schemas)\njoin matches rows across tables on a key\nunion withsource=TableName tags where each row came from",s:"Append rows from multiple tables",g:"combine",
  k:"union withsource = Src DeviceProcessEvents, DeviceNetworkEvents, DeviceFileEvents\n| where SHA1 == 'ad67d136c1db4f9f88efd94f3b6b0b5a4e2c1a0f' or InitiatingProcessSHA1 == 'ad67d136c1db4f9f88efd94f3b6b0b5a4e2c1a0f'\n| summarize count() by Src, DeviceName",
  x:"union vertically concatenates rows from two or more tables and is the tool for 'search every Device* table for this hash' questions; columns that exist in only some inputs are null in the others. join horizontally matches rows by key and is the tool for enriching one table with another. Wildcards work in union (union Device*), and withsource adds a column naming the origin table. A join across tables with no shared key is a classic wrong-answer option.",
  w:"union = stack them; join = line them up."},
 {c:"kql",obj:"3.1.2",q:"let statements — reusable values, lists and sub-queries",
  a:"#let name = value; defines a scalar, a dynamic list or a tabular expression\nEnds with a semicolon; referenced later in the same query\nmaterialize() inside let caches a tabular result evaluated once",s:"Define a named variable or sub-query for reuse",g:"combine",
  k:"let lookback = 14d;\nlet lolbins = dynamic(['certutil.exe','mshta.exe','regsvr32.exe']);\nlet susp = materialize(DeviceProcessEvents | where Timestamp > ago(lookback) and FileName in~ (lolbins));\nsusp | summarize count() by FileName\n| join kind=inner (susp | summarize dcount(DeviceName) by FileName) on FileName",
  x:"let binds a name to a scalar (time span, string), a dynamic array for use with in or has_any, or a whole tabular expression that later lines reference like a table. It makes hunting queries readable and is how reference lists and thresholds are parameterised. Wrapping a tabular let in materialize() caches it so a sub-query that is used twice, as on both sides of a join, is computed once; the cache is capped at 5 GB per node."},
 {c:"kql",obj:"3.1.2",q:"parse vs extract — pulling fields out of a string column",
  a:"#parse matches a literal pattern and names the pieces\nextract(regex, captureGroup, source) returns one regex capture\nparse_json()/todynamic() for JSON; then dot or [] access",s:"Pattern-based field extraction from text",g:"strings",
  k:"Syslog\n| where ProcessName == 'sshd' and SyslogMessage has 'Failed password'\n| parse SyslogMessage with * 'for ' User ' from ' SrcIP ' port ' Port:int *\n| summarize count() by User, SrcIP",
  x:"Unstructured text in Syslog, CommonSecurityLog Message or AdditionalFields needs extraction before you can summarize. parse walks the string against a template with * wildcards and captures named columns, which is fast and readable for stable formats. extract applies a regular expression and returns a numbered capture group, better for variable formats. JSON columns are handled differently: parse_json or todynamic turns the string into a dynamic value whose properties you address with dot notation and cast with tostring or toint."},
 {c:"kql",obj:"3.1.2",q:"mv-expand — turning a dynamic array into one row per element",
  a:"#mv-expand splits an array (or property bag) column into multiple rows\nUsed on AlertIds, LoggedOnUsers, make_set output, JSON lists in AdditionalFields\nThe expanded value is dynamic; cast with tostring() before joining",s:"Explode an array into one row per element",g:"strings",
  k:"DeviceInfo\n| summarize arg_max(Timestamp, *) by DeviceId\n| mv-expand User = parse_json(LoggedOnUsers)\n| extend UserName = tostring(User.UserName)\n| summarize Devices = dcount(DeviceId) by UserName\n| where Devices > 5",
  x:"Many hunting tables store lists inside a single dynamic column, for example the users signed in to a device, the alert IDs behind an incident, or the recipients of a message. mv-expand duplicates the row once per element so you can filter, count and join on individual values. The opposite direction, collapsing many rows into one array, is summarize make_set or make_list. Casting the expanded element with tostring is required because join keys must be strongly typed."},
 {c:"kql",obj:"3.1.2",q:"sort/order, top, take/limit, distinct — controlling what comes back",
  a:"#sort by Col desc (order by is an alias); top N by Col combines sort + limit\ntake N / limit N return N arbitrary rows without sorting\ndistinct returns unique combinations of the listed columns",s:"Order, cap and de-duplicate results",g:"shape",
  k:"EmailEvents\n| where ThreatTypes has 'Malware'\n| summarize Hits = count() by SenderFromAddress\n| top 10 by Hits desc",
  x:"These operators shape the end of a query. sort by (or order by) arranges rows, defaulting to descending; top N by combines the sort and the cap in one step and is the right answer for 'the ten noisiest senders'. take and limit are interchangeable and return the first N rows the engine happens to produce, so they are for previewing data, not ranking. distinct removes duplicate rows across the named columns and is often faster than summarize when no aggregate is needed."},
 {c:"kql",obj:"3.1.2",q:"has vs contains vs startswith vs matches regex — which string operator to choose",
  a:"#has matches a whole indexed term (3+ chars) — fastest; contains is any substring\nstartswith/endswith anchor the match; matches regex for patterns\nAll are case-insensitive unless the _cs variant is used; matches regex is case-sensitive",s:"Term match (has) beats substring scan (contains)",g:"strings",
  k:"// 'KustoExplorerQueryRun' has 'Explorer'      -> false (not a separate term)\n// 'KustoExplorerQueryRun' contains 'Explorer' -> true\nDeviceProcessEvents\n| where ProcessCommandLine has 'Invoke-Mimikatz'\n| where ProcessCommandLine contains '-nop'",
  x:"KQL indexes text as terms (maximal alphanumeric runs of three or more characters). has looks a term up in that index and is far cheaper than contains, which scans for any substring; the trade-off is that has will not find a fragment inside a longer word. startswith and endswith anchor matches, and matches regex accepts a regular expression. Microsoft's guidance is to prefer has over contains and case-sensitive operators (has_cs, ==) when the data allows.",
  w:"has = whole word, indexed; contains = any substring, slow."},
 {c:"kql",obj:"3.1.2",q:"has_any, has_all, in, in~ — matching against a list of values",
  a:"#has_any: any term from the list; has_all: every term; in: exact match to any list element\nin and == are case-sensitive; in~ and =~ are case-insensitive\nLists can be a dynamic literal, a let variable or a sub-query",s:"Compare a column against several values at once",g:"strings",
  k:"let bad = dynamic(['certutil.exe','bitsadmin.exe','mshta.exe']);\nDeviceProcessEvents\n| where FileName in~ (bad)\n| where ProcessCommandLine has_any ('http://','https://','-urlcache')",
  x:"When one column must be checked against many values, has_any (term match on any value), has_all (every value present) and in (exact equality with any list element) replace long chains of or. The tilde versions in~ and !in~ relax case sensitivity, mirroring =~ for equality. in also accepts a tabular sub-query that returns one column, which is how a watch-list or threat-intel list is applied. has_any is the usual pick for command-line keyword hunts."},
 {c:"kql",obj:"3.1.2",q:"String equality case sensitivity: == vs =~ and the _cs operator family",
  a:"#== and != are case-sensitive; =~ and !~ are case-insensitive\nhas, contains, startswith are case-INsensitive by default; add _cs for sensitive\nin is sensitive, in~ is not",s:"Tilde relaxes case for equality and in",g:"strings",
  k:"DeviceProcessEvents\n| where FileName == 'PowerShell.exe'   // misses powershell.exe\n| where FileName =~ 'powershell.exe'  // matches any casing",
  x:"Case rules are a favourite trap. For equality the plain operator is case-sensitive and the tilde form is not, so a filter on FileName == 'powershell.exe' silently misses 'PowerShell.exe'. The text operators go the other way: has, contains, startswith and endswith ignore case by default and have _cs variants when you want sensitivity. Since case-sensitive comparisons are faster, use them when you control the casing (for example after tolower()).",
  w:"== strict, =~ relaxed; has relaxed, has_cs strict."},
 {c:"kql",obj:"3.1.2",q:"Time functions: ago(), between, startofday(), datetime_diff(), format_datetime()",
  a:"#ago(7d) = now minus a timespan; Timestamp between (start .. end)\nstartofday/startofweek truncate; datetime_diff('minute', later, earlier) returns a number\nformat_datetime(t, 'yyyy-MM-dd HH:mm') renders text",s:"Relative windows, ranges and date arithmetic",g:"timefn",
  k:"EmailEvents\n| where Timestamp between (startofday(ago(1d)) .. startofday(now()))\n| extend Hour = format_datetime(Timestamp, 'HH')\n| summarize count() by Hour",
  x:"Hunting queries scope time explicitly because the portal time picker is only a default. ago() gives a relative start, between (a .. b) bounds a range, and startofday or startofweek align windows to calendar boundaries. datetime_diff computes the gap between two timestamps in a chosen unit, which is how dwell time or 'minutes between first logon and first exfil' is derived, and format_datetime turns a datetime into a string for grouping or display. Timespans use literals such as 30m, 2h, 7d."},
 {c:"kql",obj:"3.1.2",q:"Type conversion and conditionals: tostring(), toint(), iff(), case()",
  a:"#tostring/toint/tolong/todatetime cast values, usually after JSON extraction\niff(cond, a, b) is a two-way choice; case(c1, r1, c2, r2, default) is multi-way\nDynamic values must be cast before join or in comparisons",s:"Cast dynamic values and compute conditional labels",g:"timefn",
  k:"DeviceNetworkEvents\n| extend Port = toint(RemotePort)\n| extend Svc = case(Port == 3389, 'RDP', Port == 445, 'SMB', Port in (22, 23), 'Shell', 'Other')\n| extend External = iff(RemoteIPType == 'Public', true, false)\n| summarize count() by Svc, External",
  x:"Columns pulled from JSON (AdditionalFields, RawEventData, Entities) come back as dynamic and must be converted with tostring, toint, tolong, todatetime or tobool before they can be compared reliably or used as join keys. iff evaluates a single condition and returns one of two values; case walks a list of condition/result pairs and returns the first match or the trailing default. These are the building blocks for severity labels and classification columns in hunting output."},
 {c:"kql",obj:"3.1.2",q:"count vs summarize count() — two ways to count",
  a:"#| count returns a single number of rows (column named Count)\nsummarize count() by X returns one row per group with column count_\nsummarize count() without by = one total row",s:"Total row count vs per-group counts",g:"shape",
  k:"DeviceEvents\n| where ActionType == 'AntivirusDetection'\n| count\n// versus\nDeviceEvents\n| where ActionType == 'AntivirusDetection'\n| summarize Detections = count() by DeviceName",
  x:"The count operator ends a query with one row containing the total number of rows that reached it. summarize count() is the aggregation function and produces a count per group named in the by clause (or one row with no by), and its default column name is count_ unless you alias it. Custom detection rules and analytics rules that need a threshold per entity use the summarize form, because they must keep the entity column alongside the number."},
 {c:"kql",obj:"3.1.2",q:"render, search and externaldata — visualise, sweep and import",
  a:"#render timechart | barchart | piechart draws a summarized result\nsearch 'term' sweeps all tables/columns (slow; adds $table column)\nexternaldata(schema) [@'url'] with(format='csv') reads a reference list from blob/GitHub",s:"Chart output, broad text sweep, external reference list",g:"combine",
  k:"let bad_ips = externaldata(ip:string)[@'https://raw.githubusercontent.com/contoso/blocklist/main/ips.txt'] with(format='txt');\nDeviceNetworkEvents\n| where RemoteIP in (bad_ips)\n| summarize count() by bin(Timestamp, 1d)\n| render timechart",
  x:"Three operators sit at the edges of a hunt. render is a presentation hint placed last that turns a summarize-by-time result into a chart. search scans every column of every table (or those named with in) for a term and is handy for a first look at an unknown indicator, but it is expensive and not something to put in a scheduled rule. externaldata pulls a small file (under 100 MB) from a URL or storage account into a table shape, so public block-lists can be joined without ingestion; it is not allowed in NRT rules or data lake KQL jobs."},
 /* ---------- kql: 3.1.3 advanced hunting mechanics ---------- */
 {c:"kql",obj:"3.1.3",q:"Advanced hunting quotas — retention, result rows, timeout",
  a:"#Native Defender XDR data: 30 days; Sentinel tables: their analytics-tier retention\nResult set 100,000 rows and 64 MB per query; 10-minute timeout\nCPU quota per tenant, refreshed every 15 minutes (warning above 10%)",s:"30 days, 100k rows, 64 MB, 10 minutes",g:"ahmech",
  x:"Advanced hunting over native XDR tables only reaches back 30 days; anything older requires onboarding a Sentinel workspace and extending analytics-tier retention, or streaming to external storage. Each query returns at most 100,000 rows or 64 MB and is cut off at ten minutes, and the tenant has a CPU allocation that the portal warns about above 10 percent and blocks at 100 percent until the next 15-minute cycle. Queries are written in UTC and results are shown in the portal time zone.",
  w:"30 days back, 100k rows out, 10 minutes max."},
 {c:"kql",obj:"3.1.3",q:"Columns a query must return to be used as a custom detection rule",
  a:"#Timestamp (or TimeGenerated) and ReportId\nFor Defender for Endpoint tables also DeviceId (device-group scoping, process tree)\nPlus at least one entity column: DeviceName, AccountObjectId, RecipientEmailAddress…",s:"Timestamp, ReportId and an entity identifier",g:"ahmech",
  k:"DeviceEvents\n| where ingestion_time() > ago(1d) and ActionType == 'AntivirusDetection'\n| summarize (Timestamp, ReportId) = arg_max(Timestamp, ReportId), Hits = count() by DeviceId, DeviceName\n| where Hits > 5",
  x:"A hunting query becomes a detection only if its output can be mapped back to events and assets. Timestamp sets the alert time, ReportId identifies the triggering record so the alert can show the original event, and DeviceId lets Defender apply device-group permissions and build the process tree. Summarize throws these away unless you carry them through with arg_max, which is the pattern the documentation shows. Queries lacking entity columns still run, but the alerts will have no impacted assets to act on.",
  w:"summarize eats Timestamp and ReportId; arg_max them back."},
 {c:"kql",obj:"3.1.3",q:"'Go hunt' and 'Hunt for related events' — launching a query from an incident",
  a:"#Go hunt appears on entities in the incident summary and Evidence tab\nHunt for related events appears on a device timeline event: ±30 minutes across tables\nBoth open advanced hunting with a prefilled query you can edit",s:"Prefilled hunting query from an entity or timeline event",g:"ahmech",
  k:"// generated shape for a timeline event\nlet selectedTimestamp = datetime(2026-09-30T14:02:11Z);\nunion DeviceProcessEvents, DeviceNetworkEvents, DeviceFileEvents\n| where Timestamp between ((selectedTimestamp - 30m) .. (selectedTimestamp + 30m))",
  x:"The go hunt action bridges incident investigation and advanced hunting. From a user, device, file, IP, URL, mailbox or email entity it builds a query scoped around the earliest activity of that entity in the incident, and from a device timeline row it builds a union across the relevant schema tables for a thirty-minute window either side of the selected event, labelling rows as earlier, selected or later. Because the query is just text in the editor, you can widen the window or add filters before running."},
 {c:"kql",obj:"3.1.3",q:"My queries vs Shared queries vs Community queries in advanced hunting",
  a:"#My queries: saved privately for you\nShared queries: visible to everyone in the tenant\nCommunity queries: Microsoft's public GitHub (Azure-Sentinel repo) surfaced in the portal",s:"Private, tenant-wide or GitHub-sourced saved queries",g:"ahmech",
  x:"Save query > Save as lets you choose a folder: My queries keeps a query personal, Shared queries publishes it to every analyst in the organisation, and the Community queries folder is read-only content pulled from Microsoft's GitHub hunting repository, organised by category. A Share link button produces a URL that opens the editor with the query loaded. Deleting is permanent, so rename rather than delete when you want to keep history. Saved queries can also be exposed as functions and as custom MCP tools."},
 {c:"kql",obj:"3.1.3",q:"'Take action' from advanced hunting results — what can be done and which column is needed",
  a:"#Devices (DeviceId): isolate, collect investigation package, run AV scan, start AIR, restrict app execution\nFiles (DeviceId + SHA1/SHA256): quarantine; Users (AccountObjectId / AccountSid): disable, reset auth\nEmail (NetworkMessageId): move to folder, soft/hard delete, submit to Microsoft; tracked in Action center",s:"Remediate devices, files, users or email from results",g:"ahmech",
  k:"EmailEvents\n| where ThreatTypes has 'Phish' and DeliveryAction == 'Delivered'\n| project NetworkMessageId, RecipientEmailAddress, EmailDirection, SenderFromAddress, LatestDeliveryLocation",
  x:"Selecting rows in the results grid and choosing Take action lets you respond without leaving the hunting page. The available actions depend on which identifier columns the query projected: a DeviceId unlocks device actions, a hash alongside DeviceId unlocks file quarantine, an account object ID or SID unlocks identity actions, and NetworkMessageId with EmailDirection and SenderFromAddress unlocks mail moves and deletes. Every action is logged with an approval ID in the Action center History tab and needs the matching response permission.",
  w:"No identifier column, no action button."},
 {c:"kql",obj:"3.1.3",q:"Query resources report — finding expensive advanced hunting queries",
  a:"#Lists queries run in the last 30 days with CPU usage (Low/Medium/High)\nShows query time, state (completed, failed, throttled), time range and interface (portal, API, custom detection)\nUse it when the tenant hits CPU quota warnings",s:"Report of CPU-heavy queries over the last 30 days",g:"ahmech",
  x:"When advanced hunting starts throttling, the Query resources report shows which queries are responsible. It ranks executions from the past 30 days by resource consumption, tells you whether they came from the portal, the API or a scheduled custom detection, and flags failed or throttled runs. Typical fixes are narrowing the time range, filtering before join, replacing contains with has and reducing the frequency of heavy custom detections. The report is reached from the advanced hunting page."},
 {c:"kql",obj:"3.1.3",q:"Advanced hunting in the Defender portal vs Logs in the Azure portal",
  a:"#Defender portal advanced hunting is unified: XDR tables, Sentinel workspace tables and data lake in one editor\nTimestamp (XDR) vs TimeGenerated (Sentinel); custom functions from the workspace are usable\nSecurity Copilot can write KQL from natural language there",s:"One editor over XDR, workspace and lake tables",g:"ahmech",
  k:"// XDR table and Sentinel table side by side in the Defender portal\nDeviceLogonEvents | where Timestamp > ago(1d)\n| join kind=inner (SecurityEvent | where EventID == 4624 and TimeGenerated > ago(1d)) on $left.DeviceName == $right.Computer",
  x:"Once a workspace is onboarded to the Defender portal, advanced hunting becomes the single hunting surface: it queries native XDR tables, every table in the connected Sentinel workspace and, through the data lake, longer history, with Security Copilot available to draft KQL. The Azure portal Logs blade only sees the workspace. Watch the time column: XDR tables use Timestamp while Log Analytics tables use TimeGenerated, and the Defender portal scope can be the tenant or a selected workspace."},

 /* ---------- xdrhunt: 3.1.4 threat analytics & threat intelligence ---------- */
 {c:"xdrhunt",obj:"3.1.4",q:"Threat analytics dashboard — the three headline sections",
  a:"#Latest threats, High-impact threats, Highest exposure threats\nImpact is ranked by active and resolved alerts in your tenant\nExposure is computed from vulnerability severity and vulnerable device count",s:"Latest, high-impact and highest-exposure threat lists",g:"ta",
  x:"Threat analytics is Microsoft's in-product threat intelligence feed, reached from the Defender portal navigation. The dashboard opens with three lists: the most recently published or updated reports, the threats generating the most alerts in your organisation, and the threats you are most exposed to based on unpatched vulnerabilities. The difference between impact (what already fired) and exposure (what could) is a common exam angle.",
  w:"Impact = alerts you already have; exposure = holes you still have."},
 {c:"xdrhunt",obj:"3.1.4",q:"Sections of a threat analytics report",
  a:"#Overview, Analyst report, Related incidents, Impacted assets, Endpoints exposure, Recommended actions\nAnalyst report = the researcher write-up with attack chain, techniques and hunting guidance\nImpacted assets lists devices, users, mailboxes, apps and cloud resources",s:"Overview, analyst report, incidents, assets, exposure",g:"ta",
  x:"Each report follows the same layout. Overview summarises the threat with charts of organisational impact and MITRE techniques; Analyst report is the detailed narrative written by Microsoft researchers, including recommended hunting queries; Related incidents lists your incidents tied to the threat; Impacted assets shows which of your assets had active or resolved alerts; Endpoints exposure shows patch status for the relevant CVEs; Recommended actions lists mitigations. An Indicators tab with IOCs is in preview for verified customers.",
  w:"Hunting queries hide in the Analyst report tab."},
 {c:"xdrhunt",obj:"3.1.4",q:"Threat tags used to filter threat analytics reports",
  a:"#Ransomware, Phishing, Vulnerability, Activity group\nPlus a Category filter such as Actor or OSINT report type\nFilters are applied from the Filters button on the report list",s:"Ransomware, phishing, vulnerability, activity group",g:"ta",
  x:"Reports carry threat tags so an analyst can narrow the list to what matters for a task: the four tags are ransomware, phishing, vulnerability and activity group (the threat actor profiles). A separate category filter distinguishes actor profiles and open-source intelligence articles from other analyst reports. The same tags drive the threat analytics email notification settings, where you choose which tagged reports trigger an email.",
  w:"Four tags: ransomware, phishing, vulnerability, activity group."},
 {c:"xdrhunt",obj:"3.1.4",q:"Reading 'Impacted assets' vs 'Endpoints exposure' on a threat report",
  a:"#Impacted assets = entities with active or resolved alerts for this threat (post-breach)\nEndpoints exposure = devices still missing the relevant security updates (pre-breach)\nTogether they answer 'are we hit?' and 'could we be hit?'",s:"Alerted assets versus unpatched devices",g:"ta",
  x:"Two tabs on a report are easy to confuse. Impacted assets is evidence of detection: devices, users, mailboxes, apps and cloud resources that already have alerts mapped to the threat, with their alert state. Endpoints exposure is posture: the share of devices where the vulnerabilities the threat exploits remain unpatched, drawn from Defender Vulnerability Management. A stem asking which devices should be patched first points at exposure; one asking which incidents to triage points at impacted assets or related incidents."},
 {c:"xdrhunt",obj:"3.1.4",q:"Threat intelligence in the Defender portal — Intel explorer and intel profiles (MDTI)",
  a:"#Threat intelligence > Intel explorer: search campaigns, indicators, threat actors, tools, vulnerabilities, reports\nIntel profiles describe actors, tools and CVEs with associated indicators\nEntity pages get a Threat Intelligence Insights tab (reputation, articles, infrastructure)",s:"Searchable intel on actors, infrastructure and indicators",g:"ta",
  x:"Microsoft Defender Threat Intelligence content is surfaced under Threat intelligence in the Defender portal. Intel explorer searches and filters across campaigns, indicators, attack patterns, actors, tools and vulnerabilities, and intel profiles are curated pages about a specific actor or tool. IP, domain, URL and file entity pages gain a Threat Intelligence Insights tab with reputation and infrastructure relationships. Unlike threat analytics, this content is not computed against your tenant's alerts and exposure; it is reference intelligence.",
  w:"Threat analytics = Microsoft threat + your data; MDTI = the world's infrastructure."},
 {c:"xdrhunt",obj:"3.1.4",q:"Threat analytics vs the Threat intelligence overview page",
  a:"#Threat analytics reports: tenant-specific impact, exposure and mitigations per threat\nThreat intelligence overview: executive summary, latest/high-impact/highest-exposure lists, articles, notifications\nBoth live under Threat intelligence in the Defender portal",s:"Per-threat tenant impact vs the intelligence landing page",g:"ta",
  x:"The Threat intelligence section now opens with an overview page that combines a generated executive summary, the same latest, high-impact and highest-exposure lists seen on the threat analytics dashboard, article browsing and email notification setup. Threat analytics reports remain the per-threat deep dive with your related incidents and exposed endpoints. When a stem asks how to judge whether a newly published campaign affects the organisation, the report's impact and exposure data is the answer, not a generic article."},
 {c:"xdrhunt",obj:"3.1.4",q:"Using a threat analytics report to drive a hunt",
  a:"#Copy the hunting queries from the Analyst report into advanced hunting\nCheck Related incidents and Impacted assets for what already fired\nPatch via Endpoints exposure; apply Recommended actions; bookmark the report for updates",s:"Analyst report queries plus impacted assets and exposure",g:"ta",
  x:"The exam frames threat analytics as a starting point for proactive hunting rather than a read-only feed. The operational loop is: read the analyst report for the attack chain and techniques, run its advanced hunting queries across the 30-day window, review related incidents and impacted assets to see existing detections, then use endpoints exposure and recommended actions to reduce the attack surface. Reports are updated when Microsoft learns more, and email notifications can be enabled for new or updated reports by tag."},
 /* ---------- xdrhunt: 3.1.5 hunting graphs and blast radius ---------- */
 {c:"xdrhunt",obj:"3.1.5",q:"Where the hunting graph is opened in the Defender portal",
  a:"#Investigation & response > Hunting > Advanced hunting, then the hunting graph icon or Create new > Hunting graph\nOpens a 'New graph' tab beside your KQL tabs\nRun a predefined scenario with inputs, then explore nodes and edges",s:"Advanced hunting page, Create new > Hunting graph",g:"hg",
  x:"The hunting graph is not a separate menu item; it is a graph tab inside advanced hunting. From the toolbar you pick the graph icon or Create new and choose Hunting graph, which opens a New graph tab. You then select a predefined scenario, supply its inputs (a device, a user, a storage account), optionally set filters, and select Run scenario to render an interactive graph of nodes (entities) and edges (relationships). Findings can be pivoted back into KQL for further work.",
  w:"Graph lives inside advanced hunting, not in Exposure management."},
 {c:"xdrhunt",obj:"3.1.5",q:"Predefined hunting graph scenarios — representative names",
  a:"#Attack paths to critical asset; Paths between two entities; Entity relationship map\nPaths to domain admins; Kerberoast paths to critical assets; Access to key vaults\nFilter the scenario list by MITRE technique buttons",s:"Scenario templates such as attack paths to a critical asset",g:"hg",
  x:"Rather than writing graph queries, analysts choose from a list of prebuilt scenarios (around twenty) that each answer a hunting question: potential lateral movement routes to a critical asset, every path connecting two named entities, the direct relationships of one entity, routes from non-privileged users to Domain Admins, Kerberoast or AS-REP roast escalation paths, and who can reach sensitive storage, key vaults or Kubernetes clusters. Scenarios are tagged with techniques such as lateral movement and privilege escalation so they can be filtered."},
 {c:"xdrhunt",obj:"3.1.5",q:"Hunting graph filters — shortest paths, node properties, edge types",
  a:"#Basic filter: show only the shortest paths\nSource/Target node filters: is critical, is vulnerable, is exposed to the internet, has sensitive data\nEdge type filter: has permissions to, routes traffic to, member of, can authenticate as…; edge direction",s:"Trim paths by node criticality, exposure and edge type",g:"hg",
  x:"A rendered graph can be large, so filters are applied before running the scenario. The shortest-paths toggle removes redundant longer routes. Node filters restrict the start or end of a path to assets with particular exposure insights, for example only internet-exposed sources or only critical targets. Edge filters limit which relationship types may be traversed and whether they are followed incoming, outgoing or both. These same relationship labels appear on the ExposureGraphEdges table.",
  w:"Same edge labels in the graph UI and in ExposureGraphEdges."},
 {c:"xdrhunt",obj:"3.1.5",q:"Prerequisites for hunting graph and blast radius",
  a:"#Tenant onboarded to the Microsoft Sentinel data lake\nAt least read permission in Microsoft Security Exposure Management\nThe same Entra role that grants advanced hunting",s:"Sentinel data lake plus Exposure management read access",g:"hg",
  x:"Graph experiences are built on Microsoft Sentinel graph, which runs over the Sentinel data lake, so a tenant that has not onboarded the data lake does not see the hunting graph tab or the blast radius option. Because the graph incorporates exposure data (critical assets, vulnerabilities, internet exposure), the user also needs read access to Security Exposure Management. Advanced hunting permissions carry over. A stem where the graph option is missing is usually testing the data lake prerequisite."},
 {c:"xdrhunt",obj:"3.1.5",q:"Blast radius on the incident graph — what it shows",
  a:"#Possible propagation paths from a selected node to predefined critical targets\nUp to eight top-rated attack paths drawn, full list in the side panel\nCombines post-breach incident evidence with pre-breach exposure in one graph",s:"Paths from a compromised node to critical assets",g:"hg",
  x:"Blast radius answers 'if this asset is owned, what can the attacker reach next'. From the incident attack story you select an entity and generate a graph of potential onward paths toward critical assets, scored and limited to the top eight on the canvas with the rest listed in a panel. Path length is capped at five hops for cloud, five for on-premises and three for hybrid. It is a planning view for containment priority rather than evidence of what already happened.",
  w:"Blast radius = what could still happen, drawn next to what did."},
 {c:"xdrhunt",obj:"3.1.5",q:"Critical assets and attack paths in Exposure Management",
  a:"#Critical assets: predefined and custom classifications under Exposure management > Critical assets\nAttack paths (Exposure management > Attack surface > Attack paths) run from an entry point to a critical target\nChoke points are nodes where many paths converge; a crown icon marks critical nodes",s:"Classified crown-jewel assets and paths that end at them",g:"hg",
  x:"Hunting graphs and blast radius depend on the organisation having defined what counts as critical. Exposure Management ships classifications such as domain controllers, file servers, privileged role holders and sensitive databases, and lets you add custom rules with criticality levels. Attack paths are then generated from entry points to those targets, with choke points highlighted where fixing one node breaks many paths. In every graph view, a golden crown and halo mark a critical asset and a red bug marks a vulnerability.",
  w:"Crown = critical asset; bug = vulnerable; choke point = fix me first."},
 /* ---------- xdrhunt: 3.1.6 Sentinel graph ---------- */
 {c:"xdrhunt",obj:"3.1.6",q:"Microsoft Sentinel graph — what it is",
  a:"#Graph analytics layer over the Sentinel data lake: assets, identities, activity and TI as nodes and edges\nPowers hunting graph, incident graph with blast radius, Purview data risk graphs, attack path analysis\nAuto-provisioned once the data lake is onboarded",s:"Nodes-and-edges analytics engine over the data lake",g:"sg",
  x:"Microsoft Sentinel graph represents security data as a connected graph rather than rows, so questions about relationships (who can reach what, which path leads to a domain admin) become path traversals instead of chains of KQL joins. It is the engine behind the graph experiences in the Defender portal and Purview; analysts do not query it directly except through custom graphs. The only setup is onboarding the Sentinel data lake, after which hunting graph and blast radius appear automatically.",
  w:"Sentinel graph is the engine; hunting graph and blast radius are the UIs."},
 {c:"xdrhunt",obj:"3.1.6",q:"Experiences powered by Sentinel graph, by product",
  a:"#Defender XDR: incident graph with blast radius; hunting graph in advanced hunting\nPurview: data risk graph in Insider Risk Management and Data Security Investigations\nExposure Management / Defender for Cloud: attack path analysis; Custom graphs (preview) via the Graphs page",s:"Blast radius, hunting graph, data risk graph, attack paths",g:"sg",
  x:"The exam bullet is 'analyze relationships between entities by using Sentinel Graph', and the testable detail is which surface delivers which analysis. Post-breach impact and hunting are in Defender XDR; data leak blast radius for insider risk is in Purview; pre-breach attack path analysis is in Security Exposure Management and Defender for Cloud. Custom graphs let a team author their own graph model from lake data and query it with Graph Query Language from the Graphs page in the Defender portal."},
 {c:"xdrhunt",obj:"3.1.6",q:"Sentinel graph vs the classic Sentinel investigation graph",
  a:"#Sentinel graph: data-lake scale, pre- and post-breach relationships, scenario-driven, Defender portal\nInvestigation graph: per-incident entity expansion from bookmarks and alerts in the Azure portal Sentinel\nInvestigation graph needs mapped entities on the alert or bookmark",s:"Tenant-wide relationship graph vs per-incident drill-down",g:"sg",
  x:"Two graph features share a name only loosely. The older investigation graph on a Sentinel incident expands the entities mapped on alerts and bookmarks and shows related alerts and activities for that incident. Sentinel graph is a tenant-wide model over the data lake that also knows about permissions, network reachability, vulnerabilities and critical assets, so it can show hypothetical paths that have not been alerted on. When a stem mentions privilege escalation paths or blast radius, it means Sentinel graph."},
 {c:"xdrhunt",obj:"3.1.6",q:"Analysing entity relationships with Sentinel graph — the analyst workflow",
  a:"#From an incident: select a node, open blast radius, review top paths to critical assets\nFrom advanced hunting: Entity relationship map or Paths between two entities scenario\nPivot to KQL on ExposureGraphNodes/Edges or the source tables for evidence",s:"Blast radius, then hunting graph scenario, then KQL",g:"sg",
  x:"A typical lateral-movement investigation starts on the incident attack story with a compromised device, uses blast radius to see which critical assets are reachable and over which relationships, then switches to the hunting graph to map that device's direct relationships or the paths to a specific target. Each node and edge opens a details pane and can be expanded. Because graph output is hypothesis, the final step is confirming activity in the event tables (DeviceLogonEvents, IdentityLogonEvents) with KQL."},
 {c:"xdrhunt",obj:"3.1.6",q:"Which permissions and data feed Sentinel graph relationships",
  a:"#Relationships come from Defender for Endpoint, Defender for Identity, Defender for Cloud, Exposure Management and the data lake tables\nViewing needs advanced hunting rights plus Exposure management read\nNo graph without the data lake onboarded",s:"Defender sensors and exposure data; read permissions",g:"sg",
  x:"Edges such as 'has permissions to', 'can authenticate as', 'routes traffic to' and 'member of' are derived from the products already feeding the Defender portal: endpoint and identity sensors, cloud posture from Defender for Cloud, and the exposure graph. Users see graphs with the same role that grants advanced hunting, plus read access to Security Exposure Management for the criticality overlay. This is why a tenant that runs Sentinel only in the Azure portal, without the data lake and Defender portal onboarding, cannot answer graph-style questions."},
 /* ---------- senthunt: 3.2.1 hunting queries, hunts, bookmarks ---------- */
 {c:"senthunt",obj:"3.2.1",q:"Sentinel Hunting page — Queries tab essentials",
  a:"#Microsoft Sentinel > Threat management > Hunting > Queries\nRun all queries or Run selected queries; Results and Results delta columns show match counts\nMITRE tactic bar and Techniques column classify queries; sources are Content hub and your own",s:"Run all, results count, results delta, tactic bar",g:"hq",
  x:"The Hunting page lists every hunting query installed from content hub solutions plus custom ones. Run all queries executes the whole set and fills the Results column; Results delta and delta percentage compare the last 24 hours with the previous day so a sudden rise stands out. Icons across the top count queries per MITRE tactic and double as filters, and the Techniques column lists sub-techniques. N/A in results means the query's data source is not connected.",
  w:"Results delta is the 'what changed since yesterday' column."},
 {c:"senthunt",obj:"3.2.1",q:"Creating a custom hunting query and promoting it to a detection",
  a:"#Queries tab > New query (or clone a template); set description, tactics, techniques, entity mapping\nRight-click or query actions > Create analytics rule opens the rule wizard prefilled with name, description and KQL\nHunting queries only run on demand; analytics rules run on a schedule and raise alerts",s:"New query, then Create analytics rule from the hunting page",g:"hq",
  x:"A hunting query is saved KQL with metadata (tactics, techniques, entity mappings, description) that runs only when an analyst runs it. Once a hunt has proven the logic finds real activity at a tolerable false-positive rate, the Create analytics rule action hands the query to the scheduled rule wizard with name, description and query prepopulated, and the resulting rule is linked back in the hunt's related analytics rules. The reverse direction, saving a rule as a hunting query, is done by copying the KQL.",
  w:"Hunt first, promote second: query → Create analytics rule."},
 {c:"senthunt",obj:"3.2.1",q:"Hunts feature — tracking a hypothesis end to end",
  a:"#Hunts tab > New hunt: name, description, owner, Hypothesis state (Unknown / Validated / Invalidated), Status (New / Active / Closed)\nAdd queries (cloned copies), bookmarks, entities, comments; incidents and rules created from the hunt are linked\nMetrics bar: validated hypotheses, incidents created, analytic rules created",s:"Hypothesis container with queries, bookmarks and outcomes",g:"hq",
  x:"Hunts (preview) turn ad-hoc hunting into tracked work. A hunt records a hypothesis and its state, who owns it and whether it is new, active or closed, and collects the queries used (as independent clones), the bookmarks and entities found, comments, and any incidents or analytics rules produced. Queries can be added from the Queries tab via Hunt actions > Create new hunt or Add to hunt. Creating or managing hunts needs Microsoft Sentinel Contributor or a custom role with hunts permissions.",
  w:"Hypothesis state: Unknown → Validated or Invalidated; status: New → Active → Closed."},
 {c:"senthunt",obj:"3.2.1",q:"Hunting bookmarks — what they capture and where they are stored",
  a:"#Select result rows > Add bookmark: name, tags, notes, event time column, entity mapping, MITRE tactics/techniques\nStored in the HuntingBookmark table; Bookmarks tab shows up to 1,000\nAt least one mapped entity is required to use Investigate (investigation graph)",s:"Saved result rows with notes, tags and entity mapping",g:"bm",
  x:"A bookmark preserves specific rows from a hunting or Logs query together with the query itself, analyst notes, tags and mapped entities, so a finding can be revisited or shared with the team. Bookmarks are written to the HuntingBookmark table in the workspace, which is why they can be queried in KQL and why there is a short delay before they appear on the Bookmarks tab. Entity mapping is what links a bookmark to accounts, hosts and IPs for the investigation graph and entity pages.",
  w:"Bookmark = rows + notes + entities, stored in HuntingBookmark."},
 {c:"senthunt",obj:"3.2.1",q:"Bookmark incident actions — create new or add to existing",
  a:"#Bookmarks tab > select > Incident actions > Create new incident or Add to existing incident\nBookmarks then show under the incident's Bookmarks pane\nDeleting a bookmark soft-deletes (SoftDelete = true) and leaves incident entities intact",s:"Turn findings into an incident or attach to one",g:"bm",
  x:"Bookmarks are how hunting results enter the incident workflow without an analytics rule. From the Bookmarks tab (or from inside a hunt) you select one or more bookmarks and either create a new incident, optionally setting severity and owner, or add them to an incident that already exists; the incident's full details page lists them under Bookmarks. Other bookmark actions include View source query, View bookmark logs and Investigate. A stem that says 'preserve this evidence and escalate it' is describing this path.",
  w:"Found it while hunting? Bookmark it, then Incident actions."},
 {c:"senthunt",obj:"3.2.1",q:"Livestream in Sentinel — current status and replacements",
  a:"#Livestream sessions are no longer available\nFor continuous monitoring use KQL jobs (persist results), analytics rules (alerts) or playbooks (notifications)\nThe Hunting page keeps only the Queries and Bookmarks tabs",s:"Retired; use KQL jobs, analytics rules or playbooks",g:"hq",
  x:"Older material describes a Livestream tab where a hunting query ran interactively and new matches streamed in, with an option to elevate it to an alert rule. Microsoft has retired livestreams; the documentation now points to KQL jobs for scheduled, persisted results in the data lake, to analytics rules (including NRT) for alerting, and to playbooks for Teams or email notifications. If an exam option proposes creating a livestream session, treat it as a dated distractor and pick one of the replacements.",
  w:"Livestream is gone; NRT rule or KQL job instead."},
 {c:"senthunt",obj:"3.2.1",q:"Hunting in the Defender portal — where Sentinel hunting features landed",
  a:"#Microsoft Sentinel > Threat management > Hunting (queries, hunts, bookmarks) and > Notebooks\nInvestigation & response > Hunting > Advanced hunting is the unified KQL editor over XDR, workspace and lake tables\nBookmarks can be created from advanced hunting results",s:"Threat management > Hunting plus unified advanced hunting",g:"hq",
  x:"After a workspace is onboarded to the Defender portal, Sentinel's hunting queries, hunts and bookmarks appear under Microsoft Sentinel > Threat management > Hunting, with notebooks and workbooks as sibling items. Ad-hoc KQL moves to the unified advanced hunting page, which can scope to the tenant or to a workspace, reuse workspace functions and saved queries, and bookmark result rows. Microsoft has announced that after March 31, 2027 Sentinel will be available only in the Defender portal."},
 /* ---------- senthunt: 3.2.2 KQL jobs ---------- */
 {c:"senthunt",obj:"3.2.2",q:"KQL job in the Sentinel data lake — what it is for",
  a:"#A one-time or scheduled KQL query over data lake tier (and federated) tables whose results are written to a table\nUses: long lookback investigations, retrospective TI matching, aggregation, promoting lake data to the analytics tier\nCreated from Microsoft Sentinel > Data lake exploration > Jobs, or Create job in the KQL query editor",s:"Scheduled lake query that writes results to a table",g:"kj",
  x:"The data lake holds up to twelve years of lower-cost data that analytics rules and interactive hunting do not touch. A KQL job runs a query against that tier, on demand or on a schedule, and persists the output as a table, so an analyst can sweep a year of firewall logs for a newly published indicator, build an enrichment table, or promote a filtered slice into the analytics tier where rules and workbooks can use it. Jobs can span multiple workspaces but produce exactly one output table.",
  w:"Lake data is cheap to keep but needs a job to act on."},
 {c:"senthunt",obj:"3.2.2",q:"KQL job destination tables — naming and tier",
  a:"#New table in the analytics tier: name gets the _KQL_CL suffix (higher storage rate, usable by rules and workbooks)\nNew table in the data lake tier: _KQL suffix (lower cost)\nExisting table: no suffix added; federated tables cannot be targets",s:"_KQL_CL for analytics tier, _KQL for lake tier",g:"kj",
  x:"When you create a job you choose where results land, and the suffix tells you the tier. Writing to the analytics tier creates a custom table named with _KQL_CL and is the data promotion pattern, so keep the query narrow with project and where to avoid paying analytics ingestion for columns you do not need. Writing to the lake tier (_KQL) keeps it cheap for later lake queries. You may also append to an existing table you own. Timestamps older than two days are overwritten in TimeGenerated, so preserve the original in another column.",
  w:"Suffix tells the tier: _KQL_CL = analytics, _KQL = lake."},
 {c:"senthunt",obj:"3.2.2",q:"One-time vs scheduled KQL jobs",
  a:"#One-time runs immediately after creation (editing re-runs it)\nScheduled runs by minute, hourly, daily, weekly or monthly within a date range, or indefinitely\nScheduled start must be at least 30 minutes after creation; lookback can reach 12 years",s:"Run once now, or on a recurring schedule",g:"kj",
  x:"A one-time job is the investigator's tool: write the query, pick a destination, and it executes as soon as it is saved, returning history that the interactive editor would time out on. A scheduled job is the operations tool for recurring aggregation or detection-style sweeps, with a frequency, a start date and either an end date or run indefinitely; the start time must sit at least half an hour after you save. Because lake ingestion can lag by about 15 minutes, scheduled queries should subtract a delay from now() before applying the lookback.",
  w:"Scheduled jobs: start ≥ 30 minutes out, allow ~15 minutes of ingestion lag."},
 {c:"senthunt",obj:"3.2.2",q:"KQL job limits and unsupported operators",
  a:"#Per tenant: 5 concurrent executions (extra requests rejected), 100 enabled jobs, 1-hour query timeout, 1 output table per job\nNot supported: adx(), arg(), externaldata(), ingestion_time(), user-defined functions\nJobs whose source workspace is deleted move to Disabled",s:"5 concurrent, 100 enabled, 1 hour, 1 output table",g:"kj",
  x:"Numbers that distinguish KQL jobs from analytics rules: a tenant may have 100 enabled jobs with at most five running at once, and any single run is cut off after one hour. Each job writes to one table only. The lake query engine does not support cross-service operators, externaldata, ingestion_time or saved functions, so queries written for the analytics tier may need rework. These are per-tenant limits, not per user, and a rejected run is not queued.",
  w:"Five at once, a hundred on, one hour each, one table out."},
 {c:"senthunt",obj:"3.2.2",q:"Permission needed for a KQL job to create an analytics-tier table",
  a:"#Assign Log Analytics Contributor on the workspace to the data lake managed identity (msg-resources-GUID)\nDone in the Azure portal: workspace > Access control (IAM) > Add role assignment > Managed identity\nThe job author needs Entra roles with read across workspaces and write to the analytics tier",s:"Log Analytics Contributor for the lake managed identity",g:"kj",
  x:"Promotion jobs fail silently if the data lake's own identity cannot write to the target workspace. The lake uses a managed identity named msg-resources followed by a GUID, and that identity must hold Log Analytics Contributor on each workspace where jobs create analytics-tier tables. The assignment is made through Access control (IAM) on the workspace. Separately, the person creating jobs needs directory roles that allow reading the source tables and scheduling jobs across the tenant.",
  w:"The lake writes as msg-resources-GUID; give it Log Analytics Contributor."},
 {c:"senthunt",obj:"3.2.2",q:"KQL job vs hunting query vs summary rule — picking the mechanism",
  a:"#Hunting query: on-demand, analytics tier, results not stored\nKQL job: lake tier, scheduled or one-time, results stored (promotion)\nSummary rule: analytics or auxiliary source, fixed bins, aggregated results to an Analytics _CL table",s:"Interactive, lake sweep, or scheduled aggregation",g:"kj",
  x:"Three features all run KQL on a schedule-like basis, so stems hinge on the source tier and what happens to results. A hunting query is interactive and leaves nothing behind except bookmarks. A KQL job is the only one that reads the data lake tier and can reach years back, writing results to a lake or analytics table. A summary rule aggregates high-volume data in bins of 20 minutes to a day into an analytics custom table so that cheap tiers become reportable; it is not meant for ad-hoc historical investigation."},
 /* ---------- senthunt: 3.2.3 summary rules ---------- */
 {c:"senthunt",obj:"3.2.3",q:"Summary rules — purpose and destination",
  a:"#Aggregate large, noisy datasets in the background into a compact Analytics-tier custom table (name ends in _CL)\nSummaries are queryable by analytics rules, hunting, workbooks and long-range reporting\nReduces cost (keep verbose logs in a cheap tier) and can strip sensitive fields",s:"Background aggregation into an Analytics _CL table",g:"sr",
  x:"Summary rules exist for data too large or too cheaply stored to query directly: network, firewall, proxy and cloud audit logs. The rule runs a KQL aggregation on a fixed cadence and writes the result rows (counts per IP, first and last seen, sets of vendors) into a custom table on the Analytics plan, which then feeds detections, workbooks and threat-intelligence matching over long ranges. Azure Monitor adds _RuleName, _BinSize and _BinStartTime columns to each summary row.",
  w:"Summarise the haystack into a small table the rules can afford to read."},
 {c:"senthunt",obj:"3.2.3",q:"Summary rule scheduling — bin size, delay, start time",
  a:"#Frequency (bin size) in minutes: 20, 30, 60, 120, 180, 360, 720 or 1440\nOptional delay to wait for late-arriving data; start time for the first bin\nNo time filter in the query: the bin defines the window on TimeGenerated",s:"Bins from 20 minutes to 24 hours; no where on time",g:"sr",
  x:"The wizard under Microsoft Sentinel > Configuration > Summary rules asks for name, destination table, query, frequency, optional delay in minutes and start time. The frequency is the bin: each run summarises exactly one bin of TimeGenerated, so the query must not include its own time filter. Delay accounts for ingestion latency so a bin is not summarised before all its data has landed. The maximum historical window is 24 hours, matching the largest bin.",
  w:"Bin sizes: 20, 30, 60, 120, 180, 360, 720, 1440 minutes."},
 {c:"senthunt",obj:"3.2.3",q:"Summary rules on Basic and Auxiliary (data lake) tables",
  a:"#Low-cost tiers can be summarised: single-table KQL plus lookup to up to 5 Analytics tables\nAnalytics-tier sources allow all operators except cross-resource/cross-service and schema-reshaping plugins\nResults always land in an Analytics-plan custom table",s:"Cheap-tier source, lookup enrichment, Analytics destination",g:"sr",
  x:"The main reason summary rules appear on SC-200 is cost architecture: ingest verbose logs to a Basic or Auxiliary (lake) table where interactive querying is limited, then run a summary rule that aggregates them into the Analytics tier for detection and reporting. On those cheap tiers the query must be single-table, but lookup can join up to five Analytics tables, which is how threat-intelligence matching against firewall logs is done. User-defined functions, union * and cross-workspace queries are not allowed.",
  w:"Cheap table in, summary table out; lookup is your only join."},
 {c:"senthunt",obj:"3.2.3",q:"Summary rule limits and prerequisites",
  a:"#100 active rules per workspace; query capped at 10 minutes (alert above 90%); records under 1 MB\nAim for output around 0.01% of source volume\nMicrosoft Sentinel Contributor role; SummaryLogs diagnostic setting adds cost",s:"100 rules, 10-minute query, Contributor role",g:"sr",
  x:"A workspace supports up to one hundred active summary rules, each run must finish inside ten minutes and no result record may exceed one megabyte, so Microsoft's guidance is to test the query on the Hunts page first and shrink the bin if it approaches the limit. Creating rules requires Microsoft Sentinel Contributor and, in the Defender portal, a workspace onboarded there. Summary rules are public cloud only, and enabling SummaryLogs diagnostics for monitoring incurs extra charges.",
  w:"Test the query in Hunts, then shrink the bin if it nears 10 minutes."},
 {c:"senthunt",obj:"3.2.3",q:"Summary rule vs KQL job — which one for which problem",
  a:"#Summary rule: recurring fixed-bin aggregation of recent data into Analytics; no lake-tier multi-year sweep\nKQL job: one-time or scheduled query over the lake, lookback up to 12 years, can promote raw rows\nBoth write custom tables; only summary rules are limited to 24-hour windows",s:"Rolling aggregation vs long-lookback lake query",g:"sr",
  x:"The two features overlap enough to be tested side by side. Choose a summary rule when the goal is an ongoing, cost-saving aggregate of high-volume logs that detections and workbooks will read every day. Choose a KQL job when the goal is to look back months or years in the lake, match historical data against new indicators, or copy a selected subset of raw events into the analytics tier for a case. A stem saying 'retrospective' or 'historical' is a job; one saying 'reduce ingestion cost for reporting' is a summary rule."},
 /* ---------- senthunt: 3.2.4 notebooks and the Sentinel MCP server ---------- */
 {c:"senthunt",obj:"3.2.4",q:"Microsoft Sentinel notebooks — platform and prerequisites",
  a:"#Jupyter notebooks hosted on an Azure Machine Learning workspace (compute runs there)\nSentinel > Threat management > Notebooks > Templates > Create from template > launch to Azure Machine Learning\nNeed a Sentinel role on the workspace plus an AML role on the ML workspace",s:"Jupyter on Azure Machine Learning, launched from Sentinel",g:"nb",
  x:"Classic Sentinel notebooks are Jupyter documents that run on Azure Machine Learning compute and query the workspace through Kqlmagic and MSTICPy. The Notebooks page offers templates such as a getting-started guide, a credential scan and a guided investigation of process alerts; Create from template clones the notebook into your AML workspace and opens it there. Two sets of permissions apply: a Sentinel role (Reader or higher) to read data and an Azure Machine Learning role to use compute.",
  w:"Notebook = Jupyter + AML workspace + MSTICPy."},
 {c:"senthunt",obj:"3.2.4",q:"MSTICPy — what it adds to a hunting notebook",
  a:"#Python package from Microsoft's threat intelligence center for notebooks\nData retrieval from Sentinel/Defender, enrichment (TI, geolocation, WHOIS), analysis and visualisation (timelines, process trees)\nConfigured through msticpyconfig.yaml",s:"Python toolkit for query, enrichment and visualisation",g:"nb",
  x:"MSTICPy is the library that makes a Sentinel notebook more than a KQL client. It provides query providers for the workspace and Defender, enrichment lookups against threat intelligence and geo-IP sources, anomaly and time-series helpers, and interactive visualisations such as event timelines and process trees that workbooks cannot draw. Templates import it and read connection details from a configuration file. Exam stems mentioning 'Python' or 'machine learning on Sentinel data' point at notebooks with MSTICPy."},
 {c:"senthunt",obj:"3.2.4",q:"Notebook vs workbook — when to reach for each",
  a:"#Workbook: built-in dashboards and reports over KQL, no code, shared in the portal\nNotebook: code (Python), custom analytics and ML, external data, bespoke visuals\nNotebooks need AML compute; workbooks need only workspace read",s:"Dashboards without code vs Python investigations",g:"nb",
  x:"Both features visualise workspace data, but the exam separates them by programmability. Workbooks are the no-code reporting layer: parameterised KQL charts and grids saved as templates and viewed in the portal. Notebooks are for analysis workbooks cannot express, such as running a clustering model over sign-ins, joining with an on-premises dataset, or producing a process tree, and they require Python skills and an Azure Machine Learning workspace. 'Custom machine learning' or 'external dataset' in a stem signals notebook.",
  w:"Chart it = workbook; compute it = notebook."},
 {c:"senthunt",obj:"3.2.4",q:"Data lake exploration notebooks in Visual Studio Code",
  a:"#Microsoft Sentinel extension for VS Code: Jupyter notebooks with PySpark over the data lake\nMicrosoftSentinelProvider class reads lake tables and save_as_table() writes to lake or analytics custom tables\nNotebook jobs run on a schedule, optionally parameterised",s:"PySpark notebooks over the lake via the VS Code extension",g:"nb",
  x:"Alongside classic AML notebooks, the Sentinel data lake has its own notebook experience: install the Microsoft Sentinel Visual Studio Code extension, attach a Spark compute session, and use the MicrosoftSentinelProvider helper to load lake tables as DataFrames and write results back with save_as_table into either tier. Notebooks can be saved as scheduled or parameterised jobs for recurring transformation, summarisation or model scoring. This is the lake-era answer to 'run Python over years of data'.",
  w:"Lake notebooks: VS Code + Spark + MicrosoftSentinelProvider."},
 {c:"senthunt",obj:"3.2.4",q:"Microsoft Sentinel MCP server — what it is",
  a:"#A hosted Model Context Protocol server exposing Sentinel data and tools to AI agents and assistants\nMCP host (VS Code, Security Copilot, Copilot Studio, Foundry) ↔ MCP client ↔ Sentinel MCP server\nSigns in with Microsoft Entra; most tools require the data lake",s:"Hosted MCP endpoint that lets agents use Sentinel tools",g:"mcp",
  x:"The Model Context Protocol is the open standard agents use to call tools. Microsoft hosts a Sentinel MCP server so that an AI client, whether GitHub Copilot in VS Code, Security Copilot, Copilot Studio or an agent built in Foundry, can search tables, query the data lake and analyse entities through natural language without the analyst writing KQL. Nothing is installed locally; the client is pointed at the server URL and authenticates with Entra. Onboarding the Sentinel data lake is a prerequisite for most tools.",
  w:"MCP = agents calling Sentinel tools over a hosted endpoint."},
 {c:"senthunt",obj:"3.2.4",q:"Sentinel MCP tool collections and their endpoints",
  a:"#Data exploration: https://sentinel.microsoft.com/mcp/data-exploration — search tables, query the lake, analyse entities\nTriage: https://sentinel.microsoft.com/mcp/triage — incident triage and hunting\nSecurity Copilot agent creation: https://sentinel.microsoft.com/mcp/security-copilot-agent-creation",s:"Data exploration, triage, agent creation",g:"mcp",
  x:"Tools are grouped into scenario collections, each with its own server URL. Data exploration is the hunting collection: it finds the right table for a question, runs queries against the data lake and runs entity analysis for a user, URL or IP. Triage wraps incident APIs so an agent can summarise and prioritise incidents and hunt over your data. The agent creation collection is for building Security Copilot agents conversationally. Saved advanced hunting queries can also be exposed as custom MCP tools.",
  w:"Hunting agents connect to the data-exploration collection."},
 {c:"senthunt",obj:"3.2.4",q:"Connecting Jupyter in VS Code to the Sentinel MCP server",
  a:"#Add the Sentinel MCP server URL to VS Code's MCP configuration and sign in with Entra\nGitHub Copilot agent mode then lists the collection's tools and can draft or run lake queries from a notebook\nUser needs at least Security Reader; data lake onboarded",s:"Add the server URL in VS Code, use Copilot agent mode",g:"mcp",
  x:"The exam bullet ties notebooks to the MCP server. In practice an analyst working in a VS Code notebook adds the Sentinel MCP endpoint as a server in the editor's MCP settings, completes the Entra sign-in, and then GitHub Copilot in agent mode can call tools such as table search and lake query to explore data and generate code for the notebook. The same server can be added as a tool collection in Security Copilot, Copilot Studio and Foundry. Permissions follow the user, so a Security Reader sees read-only tools.",
  w:"VS Code + Copilot agent mode + Sentinel MCP server = notebook that writes its own KQL."},
 {c:"senthunt",obj:"3.2.4",q:"Permissions and prerequisites for the Sentinel MCP server",
  a:"#Security Reader (minimum) to list and invoke tools; actions obey the user's existing permissions\nMicrosoft Sentinel data lake onboarded for data exploration tools\nOptional: Sentinel in the Defender portal, Defender XDR/Endpoint, Security Copilot for richer tools",s:"Security Reader plus data lake onboarding",g:"mcp",
  x:"The MCP server adds no new privilege model; it brokers calls under the identity that signed in, so an agent can only read what the person could read in the portal. Security Reader is the floor for discovering and invoking tools, and the triage collection respects whatever incident permissions the user already has. Because the data exploration tools run against the lake, tenants that have not onboarded the data lake get little from the server. Stems about 'least privilege for an AI assistant querying Sentinel' land on Security Reader.",
  w:"Agent = you: Security Reader floor, your permissions ceiling."},
];
